-- =============================================================================
-- 498 — LE CAHIER D'EXERCICES DE 3E (partie 12)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 498 --niveau 3e --fichiers grec.n1,latin.n1,musique.jumelles,sport.jumelles --suffixe 12 > supabase/contenu/498_exercices_3e_12.sql
--
-- 51 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   grec.n1                  9 exercices · 3 chapitres
--   latin.n1                 9 exercices · 3 chapitres
--   musique.jumelles         9 exercices · 3 chapitres
--   sport.jumelles          24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('0144a2de-d9ae-5f38-b84d-2b982e253814'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Des lettres grecques dans ton cartable","competence":"lire-tableau","situation":"Maëlle feuillette son manuel de maths et de physique : elle y croise des lettres étranges, qui viennent toutes de l’alphabet grec. Elle les range dans un tableau.","documents":[{"id":"lettres","type":"tableau","titre":"Les lettres grecques de Maëlle","colonnes":["Lettre","Nom","Où on la rencontre"],"lignes":[["π","pi","le périmètre du cercle (3,14…)"],["Ω","oméga","l’ohm, unité de résistance électrique"],["Δ","delta","la variation d’une grandeur"],["λ","lambda","la longueur d’onde"],["μ","mu","le préfixe « micro »"],["α","alpha","un angle, en géométrie"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la lettre grecque qui sert à écrire l’ohm.","aide":"Cherche la ligne qui parle de résistance électrique.","type":"zone","document":"lettres","multiple":false},{"enonce":"D’après le tableau, quelle lettre grecque note la longueur d’onde ?","aide":"Cherche la ligne qui parle de longueur d’onde.","type":"choix","options":[{"id":"a","texte":"lambda"},{"id":"b","texte":"mu"},{"id":"c","texte":"delta"},{"id":"d","texte":"pi"}],"multiple":false},{"enonce":"Le mot « alphabet » est fait des noms des deux premières lettres grecques.","aide":"Dans le tableau, α est la première lettre.","type":"trous","segments":["Alphabet = ",0," + ",1],"banque":["bêta","gamma","delta","alpha"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"**Ω (oméga)** désigne l’ohm, l’unité de résistance électrique. C’est la dernière lettre de l’alphabet grec."},{"cle":{"type":"choix","ids":["a"]},"explication":"**λ (lambda)** note la longueur d’onde ; μ se dit mu, Δ delta, π pi."},{"cle":{"type":"trous","trous":[["alpha"],["beta"]]},"affichage":"alpha · bêta","explication":"**Alpha** (α) puis **bêta** (β) : « alpha-bêta », d’où *alphabet*."}]$ex$::jsonb),
  ('0144a2de-d9ae-5f38-b84d-2b982e253814'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le mot gravé sur la stèle","competence":"manier-langue","situation":"Au musée, Hugo recopie un mot grec en minuscules : quatre lettres, dont deux le trompent parce qu’elles ressemblent à des lettres françaises. Il doit le lire sans se tromper.","documents":[{"id":"stele","type":"schema","titre":"Le mot recopié par Hugo","largeur":320,"hauteur":140,"elements":[{"forme":"rect","x":20,"y":30,"l":60,"h":70,"arrondi":8,"id":"z1","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":50,"y":72,"emoji":"ν","taille":40},{"forme":"rect","x":90,"y":30,"l":60,"h":70,"arrondi":8,"id":"z2","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":120,"y":72,"emoji":"ι","taille":40},{"forme":"rect","x":160,"y":30,"l":60,"h":70,"arrondi":8,"id":"z3","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":190,"y":72,"emoji":"κ","taille":40},{"forme":"rect","x":230,"y":30,"l":60,"h":70,"arrondi":8,"id":"z4","zone":true,"teinte":"sable","motif":"clair"},{"forme":"emoji","x":260,"y":72,"emoji":"η","taille":40},{"forme":"texte","x":160,"y":125,"texte":"Mot grec lu de gauche à droite","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche la lettre qui ressemble à un « n » minuscule mais qui note un E long.","aide":"Cette lettre s’appelle êta ; elle s’oppose à l’epsilon, le E bref.","type":"zone","document":"stele","multiple":false},{"enonce":"Touche la lettre qui ressemble à un « v » mais qui note un N.","aide":"Son nom est celui d’une lettre qui se prononce « nu ».","type":"zone","document":"stele","multiple":false},{"enonce":"Lis les quatre lettres de gauche à droite et écris le mot en lettres latines, comme on le prononce.","aide":"ν se lit n, ι se lit i, κ se lit k, et η se lit é.","type":"texte","placeholder":"en lettres latines"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**η (êta)** ressemble à un « n » mais se lit comme un **E long**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**ν (nu)** ressemble à un « v » mais note le son **N**."},{"cle":{"type":"texte","acceptes":["nike"]},"affichage":"nike","explication":"ν + ι + κ + η = **nikê** (« Niké », la victoire). Les deux lettres trompeuses sont ν (N) et η (E long)."}]$ex$::jsonb),
  ('0144a2de-d9ae-5f38-b84d-2b982e253814'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"D’où vient le « h » d’hippodrome ?","competence":"analyser-document","situation":"Inès affirme qu’il n’y a pas de « h » dans l’alphabet grec, donc pas de « h » dans les mots français venus du grec. Malik n’en est pas si sûr : il a un tableau sous les yeux.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Une dispute au CDI","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Il n’y a aucune lettre « h » dans l’alphabet grec, donc aucun « h » dans les mots venus du grec."},{"qui":"Malik","texte":"Alors pourquoi on écrit hippodrome avec un « h » ?"}]},{"id":"mots","type":"tableau","titre":"Cinq mots grecs et leurs descendants","colonnes":["Mot grec","Sens","Mot français"],"lignes":[["ἵππος","cheval","hippodrome"],["ἄθεος","sans dieu","athée"],["ἱστορία","enquête, récit","histoire"],["ἥλιος","soleil","héliotrope"],["ἔρημος","désert","ermite"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Que peut répondre Malik à Inès ?","aide":"Pense au signe qu’on pose sur une voyelle initiale : l’esprit rude ou l’esprit doux.","type":"choix","options":[{"id":"a","texte":"Le grec avait bien une lettre « h » dans l’alphabet, mais elle a disparu au fil des siècles"},{"id":"b","texte":"Le « h » a été ajouté au hasard par les copistes du Moyen Âge, sans lien avec le grec"},{"id":"c","texte":"Le « h » vient du latin, qui l’a mis sur tous les mots empruntés au grec"},{"id":"d","texte":"Une voyelle initiale grecque peut porter un esprit rude, qui note une aspiration que le français écrit « h »"}],"multiple":false},{"enonce":"Touche les deux mots grecs qui portent un esprit doux : leur descendant français n’a pas de « h ».","aide":"Regarde la colonne de droite : quels mots français commencent par une voyelle ?","type":"zone","document":"mots","multiple":true},{"enonce":"Combien de mots français de la colonne de droite commencent par un « h » ?","aide":"Compte hippodrome, puis les autres.","type":"nombre"},{"enonce":"D’après ce que tu viens de voir, classe ces mots français selon l’esprit de leur mot grec.","aide":"Un « h » en français vient d’un esprit rude ; pas de « h », esprit doux.","type":"categories","categories":[{"id":"c0","texte":"Esprit rude"},{"id":"c1","texte":"Esprit doux"}],"items":[{"id":"i0","texte":"amoral"},{"id":"i1","texte":"athée"},{"id":"i2","texte":"histoire"},{"id":"i3","texte":"hématome"},{"id":"i4","texte":"hippopotame"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Le grec n’a pas de lettre « h », mais l’**esprit rude** placé sur la voyelle initiale note une aspiration : le français l’écrit « h » (ἵππος → *hippodrome*)."},{"cle":{"type":"zone","ids":["r1c0","r4c0"]},"explication":"**ἄθεος** (athée) et **ἔρημος** (ermite) : esprit doux, pas de « h » en français."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"**3** : *hippodrome*, *histoire* et *héliotrope*. Ces trois mots grecs avaient un esprit rude."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"*Hippopotame*, *hématome* et *histoire* ont un « h » : esprit rude. *Amoral* et *athée* commencent par une voyelle : esprit doux."}]$ex$::jsonb),
  ('52bbd6bc-2aa3-5b92-9cd6-216cde52b1bd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Décomposer un mot savant","competence":"comprendre-langue","situation":"Dans un journal, Noé tombe sur « biologie », « philanthrope » et « politique ». Il se rappelle qu’un mot savant se lit comme une addition de racines grecques.","documents":[{"id":"racines","type":"tableau","titre":"Les racines que Noé a notées","colonnes":["Racine grecque","Sens"],"lignes":[["ἄνθρωπος (anthrôpos)","l’homme"],["λόγος (logos)","parole, science"],["φιλεῖν (philein)","aimer"],["πόλις (polis)","la cité"],["βίος (bios)","la vie"],["γράφειν (graphein)","écrire"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Que signifie littéralement « biologie », formé de bios + logos ?","aide":"Cherche le sens de bios, puis celui de logos.","type":"choix","options":[{"id":"a","texte":"Le discours sur la vie"},{"id":"b","texte":"L’amour de la vie"},{"id":"c","texte":"L’écriture de la vie"},{"id":"d","texte":"La cité de la vie"}],"multiple":false},{"enonce":"Touche la racine grecque que l’on retrouve dans « politique ».","aide":"La politique concerne la vie de la cité.","type":"zone","document":"racines","multiple":false},{"enonce":"Associe chaque mot français à sa décomposition.","aide":"Repère les racines dans chaque mot : anthrôpos, philein, polis.","type":"association","gauche":[{"id":"g0","texte":"anthropologie"},{"id":"g1","texte":"philanthrope"},{"id":"g2","texte":"politique"}],"droite":[{"id":"d0","texte":"aimer + l’homme"},{"id":"d1","texte":"l’homme + la science"},{"id":"d2","texte":"ce qui concerne la cité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"*bios* = la vie, *logos* = le discours, la science : **le discours sur la vie**."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"**πόλις (polis)**, la cité : la *politique* est ce qui concerne la cité."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"*Anthropologie* = anthrôpos + logos ; *philanthrope* = philein + anthrôpos ; *politique* vient de polis."}]$ex$::jsonb),
  ('52bbd6bc-2aa3-5b92-9cd6-216cde52b1bd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les services de l’hôpital","competence":"comprendre-langue","situation":"Dans le hall d’un hôpital, un panneau indique les services dont le nom est en grec : cardiologie, dermatologie, néphrologie… Tu dois deviner où envoyer chaque patient sans chercher dans un dictionnaire.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","entete":"Hôpital — les services","sousTitre":"Rez-de-chaussée et 1er étage","emoji":"🏥","lignes":[{"texte":"Cardiologie","valeur":"Salle A","id":"z1"},{"texte":"Dermatologie","valeur":"Salle B","id":"z2"},{"texte":"Néphrologie","valeur":"Salle C","id":"z3"},{"texte":"Pneumologie","valeur":"Salle D","id":"z4"},{"texte":"Hématologie","valeur":"Salle E","id":"z5"}],"pied":"Suivez les flèches","teinte":"bleu","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Karim doit faire contrôler ses reins. Touche le service où l’envoyer.","aide":"La racine néphr- désigne le rein.","type":"zone","document":"panneau","multiple":false},{"enonce":"Touche les deux services dont le nom contient la racine du « sang » et la racine de la « peau ».","aide":"Les racines sont hémat- et derm-.","type":"zone","document":"panneau","multiple":true},{"enonce":"Associe chaque racine grecque à la partie du corps qu’elle désigne.","aide":"Les services du panneau t’aident pour deux d’entre elles.","type":"association","gauche":[{"id":"g0","texte":"cardio-"},{"id":"g1","texte":"pneum-"},{"id":"g2","texte":"psych-"},{"id":"g3","texte":"derm-"}],"droite":[{"id":"d0","texte":"le poumon"},{"id":"d1","texte":"la peau"},{"id":"d2","texte":"l’âme"},{"id":"d3","texte":"le cœur"}]},{"enonce":"Complète avec le mot savant qui convient.","aide":"Quelle racine veut dire « cœur » ?","type":"trous","segments":["Un ",0," est un médecin du cœur."],"banque":["néphrologue","dermatologue","cardiologue","pneumologue"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Néphrologie** : néphr- = rein, -logie = étude."},{"cle":{"type":"zone","ids":["z5","z2"]},"explication":"**Hématologie** (hémat- = sang) et **dermatologie** (derm- = peau)."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"**cardio-** = cœur ; **pneum-** = poumon ; **psych-** = âme ; **derm-** = peau."},{"cle":{"type":"trous","trous":[["cardiologue"]]},"affichage":"cardiologue","explication":"Un **cardiologue** soigne le cœur : cardio- (cœur) + -logue (qui étudie)."}]$ex$::jsonb),
  ('52bbd6bc-2aa3-5b92-9cd6-216cde52b1bd'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Diamètre, périmètre, symétrie : lire les préfixes","competence":"analyser-document","situation":"En géométrie, Zoé s’aperçoit que « diamètre », « périmètre » et « symétrie » finissent tous par la même racine grecque, metron : la mesure. Ce sont les préfixes qui font la différence.","documents":[{"id":"prefixes","type":"tableau","titre":"Quelques préfixes grecs","colonnes":["Préfixe","Sens"],"lignes":[["péri-","autour"],["dia-","à travers"],["syn- / sym-","avec"],["hypo-","en dessous"],["hyper-","au-dessus"],["anti-","contre"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"cercle","type":"figure","titre":"Un cercle de centre O","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":8},"points":[{"id":"O","x":5,"y":4,"position":"s"},{"id":"A","x":2,"y":4,"position":"o"},{"id":"B","x":8,"y":4,"position":"e"}],"segments":[{"de":"A","a":"B","id":"z1"}],"cercles":[{"centre":"O","rayon":3,"id":"z2"}]}],"questions":[{"enonce":"Dia- veut dire « à travers ». Touche l’élément de la figure qui est un diamètre : une mesure faite à travers le cercle.","aide":"Cherche le segment qui traverse le cercle de part en part.","type":"zone","document":"cercle","multiple":false},{"enonce":"Péri- veut dire « autour ». Touche l’élément dont la longueur est le périmètre.","aide":"Le périmètre se mesure en faisant le tour.","type":"zone","document":"cercle","multiple":false},{"enonce":"Que signifie littéralement « symétrie » (sym- + metron) ?","aide":"Relis la ligne « syn- / sym- » du tableau.","type":"choix","options":[{"id":"a","texte":"La mesure faite avec un autre élément"},{"id":"b","texte":"La mesure faite à travers un élément"},{"id":"c","texte":"La mesure faite tout autour d’un élément"},{"id":"d","texte":"La mesure faite en dessous d’un élément"}],"multiple":false},{"enonce":"Associe chaque mot à son sens littéral.","aide":"Cherche le préfixe de chaque mot dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"hypertension"},{"id":"g1","texte":"hypotension"},{"id":"g2","texte":"antidote"},{"id":"g3","texte":"périphérie"}],"droite":[{"id":"d0","texte":"ce qui est autour du centre"},{"id":"d1","texte":"ce qu’on donne contre un poison"},{"id":"d2","texte":"une tension en dessous de la normale"},{"id":"d3","texte":"une tension au-dessus de la normale"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **segment AB**, qui passe par le centre et traverse le cercle de part en part, est un diamètre."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le périmètre est la longueur **du cercle lui-même**, mesurée tout autour."},{"cle":{"type":"choix","ids":["a"]},"explication":"sym- = avec, metron = mesure : **la mesure faite avec** un autre élément, c’est-à-dire une partie qui répond à l’autre."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**hyper-** = au-dessus, **hypo-** = en dessous, **anti-** = contre, **péri-** = autour."}]$ex$::jsonb),
  ('da02027c-0ddd-5e0d-8333-6f6fdb145388'::uuid, 1, 1, 5, 20, 3,
