  ('bd37ed59-9fb8-43c8-b2c8-55ab245e359c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Cicéron attaque Catilina","competence":"analyser-texte","situation":"En 63 av. J.-C., Cicéron est consul. Devant le Sénat, il lance une phrase restée célèbre contre Catilina, soupçonné de préparer un complot. Tu lis la phrase, puis tu la replaces dans la vie de Cicéron.","documents":[{"id":"phrase","type":"texte","genre":"source","titre":"L’ouverture de la première Catilinaire","auteur":"Cicéron, Première Catilinaire, début (63 av. J.-C.)","blocs":["Quo usque tandem abutere, Catilina, patientia nostra ?"],"source":"Citation brève"},{"id":"frise","type":"frise","titre":"La vie de Cicéron","debut":-110,"fin":-40,"pas":10,"evenements":[{"id":"z1","date":-106,"nom":"Naissance de Cicéron"},{"id":"z2","date":-63,"nom":"Consulat de Cicéron"},{"id":"z3","date":-43,"nom":"Mort de Cicéron"}]}],"questions":[{"enonce":"Touche le verbe de la phrase, celui qui veut dire « abuser ».","aide":"C’est le mot qui suit « quo usque tandem » (« jusqu’à quand »).","type":"zone","document":"phrase","multiple":false},{"enonce":"Touche le nom de celui à qui Cicéron s’adresse.","aide":"C’est un nom propre, celui du conspirateur.","type":"zone","document":"phrase","multiple":false},{"enonce":"Quelle est la traduction de la phrase de Cicéron ?","aide":"Cherche patientia nostra : « notre patience ».","type":"choix","options":[{"id":"a","texte":"Jusqu’où, Catilina, ira ta patience envers nous ?"},{"id":"b","texte":"Pendant combien de temps, Catilina, cesseras-tu de nous écouter ?"},{"id":"c","texte":"Jusqu’à quand, Sénat, supporteras-tu la patience de Catilina ?"},{"id":"d","texte":"Jusqu’à quand, Catilina, abuseras-tu de notre patience ?"}],"multiple":false},{"enonce":"Touche l’événement qui correspond à l’année de ce discours.","aide":"Cicéron le prononce alors qu’il est consul.","type":"zone","document":"frise","multiple":false},{"enonce":"D’après la frise, combien d’années séparent le consulat de Cicéron de sa mort ?","aide":"Soustrais : de -63 à -43.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**abutere** (« tu abuseras ») est le verbe : c’est un reproche direct."},{"cle":{"type":"zone","ids":["m4"]},"explication":"Cicéron interpelle **Catilina**, qu’il accuse de comploter contre la République."},{"cle":{"type":"choix","ids":["d"]},"explication":"**« Jusqu’à quand, Catilina, abuseras-tu de notre patience ? »** : *nostra* = notre, *patientia* = patience."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le discours date de **63 av. J.-C.**, l’année du consulat de Cicéron."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 ans","explication":"De 63 à 43 av. J.-C., il s’écoule **20 ans** (63 − 43 = 20)."}]$ex$::jsonb),
  ('bd37ed59-9fb8-43c8-b2c8-55ab245e359c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"« Civis Romanus sum » : la phrase qui protège","competence":"raisonner","situation":"Marcus est un commerçant romain arrêté à tort dans une ville lointaine. Pour se défendre, il n’a qu’une phrase, mais elle suffit à faire reculer l’officier.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"L’arrestation de Marcus","blocs":["Marcus, négociant romain, est arrêté par un officier qui l’accuse sans preuve. Il ne se laisse pas impressionner : « Civis Romanus sum ! » s’écrie-t-il.","L’officier hésite, puis recule : un citoyen a le droit d’être jugé selon la loi, et Marcus ne sera pas condamné sans procès."],"source":"Récit écrit pour l’exercice"},{"id":"spqr","type":"fiche","modele":"affiche","entete":"SPQR","sousTitre":"La devise de la République","emoji":"🏛️","lignes":[{"texte":"S — Senatus","valeur":"le Sénat","id":"z1"},{"texte":"PQ — PopulusQue","valeur":"et le peuple","id":"z2"},{"texte":"R — Romanus","valeur":"romain","id":"z3"}],"pied":"Senatus PopulusQue Romanus","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot latin qui signifie « citoyen ».","aide":"C’est le premier mot de la phrase de Marcus.","type":"zone","document":"recit","multiple":false},{"enonce":"Pourquoi cette phrase protège-t-elle Marcus ?","aide":"Pense aux droits du citoyen.","type":"choix","options":[{"id":"a","texte":"Seuls les magistrats ont le droit de parler latin"},{"id":"b","texte":"Un citoyen a le droit d’être jugé selon la loi"},{"id":"c","texte":"Elle prouve que Marcus est sénateur à vie"},{"id":"d","texte":"Elle oblige l’officier à payer une amende"}],"multiple":false},{"enonce":"Touche la ligne de la devise qui désigne le peuple.","aide":"Populus veut dire « peuple ».","type":"zone","document":"spqr","multiple":false},{"enonce":"Associe chaque institution de la République à son rôle.","aide":"Les comices sont les assemblées du peuple.","type":"association","gauche":[{"id":"g0","texte":"les magistrats"},{"id":"g1","texte":"le Sénat"},{"id":"g2","texte":"les comices"}],"droite":[{"id":"d0","texte":"il conseille"},{"id":"d1","texte":"ils gouvernent"},{"id":"d2","texte":"ils votent"}]},{"enonce":"Parmi ces droits, lequel appartient au citoyen romain ?","aide":"Les comices sont des assemblées de vote.","type":"choix","options":[{"id":"a","texte":"Siéger au Sénat dès la naissance"},{"id":"b","texte":"Gouverner seul comme consul à vie"},{"id":"c","texte":"Voter dans les assemblées du peuple"},{"id":"d","texte":"Ne payer aucun impôt"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"**civis** veut dire « citoyen » : *civis Romanus sum* = « je suis citoyen romain »."},{"cle":{"type":"choix","ids":["b"]},"explication":"Être citoyen, c’est avoir des droits, dont celui d’être **jugé selon la loi**, partout dans l’Empire."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**PopulusQue** : « et le peuple ». SPQR = le Sénat et le peuple romain."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Les **magistrats** gouvernent, le **Sénat** conseille, les **comices** (assemblées du peuple) votent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le citoyen peut **voter** dans les comices. Les consuls changent chaque année et le Sénat n’est pas héréditaire."}]$ex$::jsonb),
