   $ex${"titre":"D’Auguste à la chute : une frise à lire","competence":"se-reperer-temps","situation":"Pour préparer un exposé, Hugo a dressé la frise des grands repères de l’Empire romain. Il doit s’en servir pour répondre aux questions de sa classe.","documents":[{"id":"frise","type":"frise","titre":"L’Empire romain","debut":-50,"fin":500,"pas":50,"periodes":[{"id":"z1","debut":98,"fin":117,"nom":"Trajan","teinte":"ambre"},{"id":"z2","debut":161,"fin":180,"nom":"Marc Aurèle","teinte":"turquoise"}],"evenements":[{"id":"z3","date":-27,"nom":"Auguste empereur"},{"id":"z4","date":64,"nom":"Incendie de Rome"},{"id":"z5","date":212,"nom":"Édit de Caracalla"},{"id":"z6","date":476,"nom":"Fin de l’Occident"}]}],"questions":[{"enonce":"Touche la période du règne de l’« empereur philosophe ».","aide":"C’est l’empereur dont le nom commence par Marc.","type":"zone","document":"frise","multiple":false},{"enonce":"Trajan règne de 98 à 117. Combien d’années dure son règne ?","aide":"Soustrais les deux dates.","type":"nombre","unite":"ans"},{"enonce":"Combien d’années séparent l’édit de Caracalla de la fin de l’Empire d’Occident ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Que change l’édit de Caracalla en 212 ?","aide":"Le mot clé est « citoyenneté ».","type":"choix","options":[{"id":"a","texte":"Le latin devient la seule langue autorisée"},{"id":"b","texte":"Les provinces ne paient plus d’impôts à Rome"},{"id":"c","texte":"Tous les esclaves de l’Empire sont libérés"},{"id":"d","texte":"Presque tous les habitants libres deviennent citoyens"}],"multiple":false}]}$ex$::jsonb,
