   $ex${"titre":"Nemausus, une ville gauloise devenue romaine","competence":"analyser-document","situation":"Des archéologues fouillent le sol de Nîmes, que les Romains appelaient Nemausus. Leur inventaire mêle des vestiges romains et des traces de la tradition gauloise : à toi de trier.","documents":[{"id":"inventaire","type":"texte","genre":"article","titre":"L’inventaire de la fouille","blocs":["À Nemausus, les archéologues ont dégagé un forum, des thermes, un aqueduc et des arènes. Sur des tombes, ils ont lu des inscriptions en latin.","Dans le même quartier, un atelier de poterie gauloise fabrique encore des vases à l’ancienne, et un temple reste dédié à une divinité gauloise."],"source":"Article écrit pour l’exercice"},{"id":"carte","type":"carte","titre":"Où est Nîmes ?","fond":"france","lieux":[{"id":"z1","lieu":"nimes","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"lyon","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"toulouse","symbole":"lettre","lettre":"C","teinte":"corail"},{"id":"z4","lieu":"paris","symbole":"lettre","lettre":"D","teinte":"corail"}],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche les cinq éléments de l’inventaire qui montrent la romanisation.","aide":"Pense aux bâtiments publics romains et à la langue de Rome.","type":"zone","document":"inventaire","multiple":true},{"enonce":"Touche la lettre qui marque Nîmes, ville du sud de la France.","aide":"Nîmes est près du Rhône et de la Méditerranée, pas à Paris ni à Toulouse.","type":"zone","document":"carte","multiple":false},{"enonce":"Complète la définition de la romanisation.","aide":"Pense à ce qu’on lit sur les inscriptions et à ce qui règle les procès.","type":"trous","segments":["La romanisation diffuse la langue ",0,", le ",1," romain et les villes avec forum, thermes et arènes."],"banque":["latine","commerce","droit","gauloise"]},{"enonce":"Après l’édit de Caracalla (212), que devient un habitant libre de Nemausus ?","aide":"L’édit accorde la citoyenneté à presque tous les habitants libres.","type":"choix","options":[{"id":"a","texte":"Il devient esclave de Rome"},{"id":"b","texte":"Il devient sénateur"},{"id":"c","texte":"Il est citoyen romain"},{"id":"d","texte":"Il reste étranger à l’Empire"}],"multiple":false}]}$ex$::jsonb,
