   $ex${"titre":"Du disque au streaming","competence":"lire-graphique","situation":"Un magazine a mesuré, en pourcentage, comment les gens écoutent leur musique depuis 2005. Rayan lit le graphique et un extrait sur le fonctionnement d’une plateforme pour comprendre ce qui a changé.","documents":[{"id":"supports","type":"graphique","forme":"barres","titre":"Comment on écoute la musique","categories":["2005","2010","2015","2020"],"series":[{"nom":"CD et disques","valeurs":[85,65,35,10],"teinte":"gris"},{"nom":"Téléchargement","valeurs":[15,30,25,10],"teinte":"ambre"},{"nom":"Streaming","valeurs":[0,5,40,80],"teinte":"violet"}],"axeY":{"titre":"Part des écoutes","unite":"%","min":0,"max":100,"pas":20},"axeX":{"titre":"Année"},"valeurs":false,"source":"Chiffres imaginés pour l’exercice"},{"id":"melodia","type":"texte","genre":"article","titre":"Sur la plateforme Mélodia","auteur":"Texte écrit pour l’exercice","blocs":["Chaque matin, chaque abonné de Mélodia voit une liste « pour vous ».","Elle est composée par un algorithme, qui retient les titres écoutés jusqu’au bout et propose des titres proches.","Un artiste peu recommandé a donc peu de chances d’être découvert."]}],"questions":[{"enonce":"De combien de points la part du **streaming** a-t-elle augmenté entre 2015 et 2020 ?","aide":"Repère la série « Streaming » dans la légende, puis lis sa barre pour chacune des deux années.","type":"nombre","unite":"points"},{"enonce":"Touche **la première année** où le streaming dépasse les CD.","aide":"Compare, année après année, la barre du streaming et celle des CD.","type":"zone","document":"supports","multiple":false},{"enonce":"Associe chaque étape de l’industrie musicale à sa transformation.","aide":"Chaque étape change la façon dont on produit, découvre ou rémunère la musique.","type":"association","gauche":[{"id":"g0","texte":"Enregistrement"},{"id":"g1","texte":"Streaming"},{"id":"g2","texte":"Algorithmes"},{"id":"g3","texte":"Droit d’auteur"}],"droite":[{"id":"d0","text