  ('b1c96368-e4c3-5c62-81bc-956b02559cfd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le match de Lilou","competence":"analyser-texte","situation":"Lilou vient de jouer la finale du tournoi de basket. Son équipe a gagné largement. Elle raconte trois moments du match à son professeur.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le récit de Lilou","auteur":"Texte écrit pour l’exercice","blocs":["Mon équipe menait de dix points. Un adversaire est tombé et je lui ai tendu la main pour le relever.","Plus tard, le ballon a touché mon pied avant de sortir. L’arbitre n’a rien vu et a donné la remise à mon équipe, mais j’ai levé la main et j’ai avoué ma faute.","À la fin du match, je n’ai pas ri des perdants : j’ai serré la main de chacun."]}],"questions":[{"enonce":"Touche le mot qui montre que Lilou reconnaît une faute que l’arbitre n’a pas vue.","aide":"C’est un verbe du deuxième paragraphe.","type":"zone","document":"recit","multiple":false},{"enonce":"Relie chaque situation au geste de fair-play.","aide":"Relis les trois moments du récit.","type":"association","gauche":[{"id":"g0","texte":"L’arbitre n’a pas vu une faute"},{"id":"g1","texte":"Un joueur est à terre"},{"id":"g2","texte":"L’adversaire est dominé"},{"id":"g3","texte":"Le match est fini"}],"droite":[{"id":"d0","texte":"Ne pas l’humilier"},{"id":"d1","texte":"La reconnaître"},{"id":"d2","texte":"L’aider"},{"id":"d3","texte":"Serrer la main"}]},{"enonce":"Lilou avoue alors que l’arbitre n’a rien vu. Comment appeler son geste ?","aide":"Le fair-play commence là où finit la surveillance.","type":"choix","options":[{"id":"a","texte":"De la naïveté, car personne n’avait vu"},{"id":"b","texte":"De l’obéissance à l’arbitre qui regarde"},{"id":"c","texte":"Une triche déguisée pour séduire l’arbitre"},{"id":"d","texte":"Du fair-play, même sans témoin"}],"multiple":false},{"enonce":"Complète la phrase sur gagner et perdre.","aide":"Le premier verbe concerne l’adversaire battu, le second les excuses.","type":"trous","segments":["Gagner sans ",0,", perdre sans ",1,"."],"banque":["accuser","jouer","serrer","mépriser"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m54"]},"explication":"**Avouer** une faute que personne n’a vue, c’est du fair-play."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"Reconnaître la faute, **aider** celui qui est à terre, ne pas **humilier** et serrer la main : quatre gestes de fair-play."},{"cle":{"type":"choix","ids":["d"]},"explication":"Respecter la règle quand l’arbitre regarde, c’est de l’**obéissance** ; quand il ne regarde pas, c’est du **fair-play**."},{"cle":{"type":"trous","trous":[["mepriser"],["accuser"]]},"affichage":"mépriser · accuser","explication":"On gagne **sans mépriser** et on perd **sans accuser** : c’est ce qui permet de voir ce qu’il y avait à corriger."}]$ex$::jsonb),
