   $ex${"titre":"Un titre annulé, un tournoi à relire","competence":"argumenter","situation":"Un club a annulé un titre départemental pour dopage. Quelques semaines plus tard, trois équipes de ta classe jouent un tournoi. Tu relis les deux situations avec les valeurs olympiques.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Titre annulé","auteur":"Article imaginé pour l’exercice","blocs":["Le titre de Camille est annulé : un contrôle a révélé un produit interdit dans son organisme.","Elle est exclue des compétitions. Son médecin rappelle que ces produits agissent sur le cœur, les hormones et le psychisme."]},{"id":"tournoi","type":"tableau","titre":"Le tournoi de la classe","colonnes":["Équipe","Score","Comportement après le match"],"lignes":[["Rouge","12-2","Se moque des perdants"],["Bleue","2-12","Accuse l’arbitre"],["Verte","8-6","Serre la main de tous"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi le dopage est-il interdit ?","aide":"L’article cite les organes touchés.","type":"choix","options":[{"id":"a","texte":"Il fausse la compétition et met la santé en danger"},{"id":"b","texte":"Il rend le sport trop facile à regarder en direct"},{"id":"c","texte":"Il n’est interdit qu’aux sportifs adultes"},{"id":"d","texte":"Il fait perdre trop de temps aux arbitres"}],"multiple":false},{"enonce":"Que prouve une victoire obtenue en trichant ?","aide":"Pense à ce que la victoire doit mesurer.","type":"choix","options":[{"id":"a","texte":"Que l’arbitre est trop faible pour sanctionner"},{"id":"b","texte":"Que l’on est vraiment le meilleur joueur"},{"id":"c","texte":"Rien, pas même à celui qui triche"},{"id":"d","texte":"Que la règle du jeu est mauvaise"}],"multiple":false},{"enonce":"Touche le comportement de l’équipe qui cherche une excuse après sa défaite.","aide":"Elle blâme quelqu’un d’autre que son équipe.","type":"zone","document":"tournoi","multiple":false},{"enonce":"Range chaque comportement.","aide":"Pense aux gestes de gagner sans mépriser et perdre sans accuser.","type":"categories","categories":[{"id":"c0","texte":"Fair-play"},{"id":"c1","texte":"Pas de fair-play"}],"items":[{"id":"i0","texte":"Aider un adversaire à terre"},{"id":"i1","texte":"Accuser l’arbitre"},{"id":"i2","texte":"Serrer la main de tous"},{"id":"i3","texte":"Se moquer des perdants"}]},{"enonce":"Relie chaque valeur olympique à ce qu’elle demande.","aide":"Les trois valeurs sont excellence, amitié, respect.","type":"association","gauche":[{"id":"g0","texte":"Excellence"},{"id":"g1","texte":"Amitié"},{"id":"g2","texte":"Respect"}],"droite":[{"id":"d0","texte":"Placer le lien avant le résultat"},{"id":"d1","texte":"Donner son meilleur"},{"id":"d2","texte":"De la règle, de l’adversaire, de soi"}]}]}$ex$::jsonb,
